INSERT INTO don_vi_tri_thuc (id, ma, tieu_de, loai, khai_niem_id, truong_phai_id, gia_tri_kich_hoat, dieu_kien_json, noi_dung, cau_hoi, nguon_id, chuong, trang_tu, trang_den, muc_tin_cay, nhan_su_dung, ly_do_nhan, phien_ban, trang_thai, nguoi_tao, nguoi_duyet, ghi_chu) VALUES
(431, 'KAB-SEP-CHIA-KHOA-1', 'Số chìa khoá 1 — Hành tinh Mặt Trời (Sun) (Sepharial)', 'QUY_TAC', 28, 3, '1', '{"chi_so": "SEPHARIAL_CHIA_KHOA", "bang": 1}', 'Theo Sepharial (Ch.IV, tr.45 & Ch.XIV, tr.139–140), Số chìa khoá 1 gắn với Mặt Trời, biểu thị tính cá nhân mạnh mẽ (individuality), năng lực tự chủ, phẩm chất dẫn đầu nhưng cần tránh tính tự tôn thái quá. (Hành tinh theo Bảng chính Ch.III: Mặt Trời (Sun); theo Bảng Khoá nhỏ Ch.IV: Mặt Trời (Thượng giới - Tinh thần)).', 'AI', 5, 'Ch.IV & XIV', 45, 140, 'THAP', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(432, 'KAB-SEP-NGHE-1', 'Khuynh hướng nghề nghiệp theo Số chìa khoá 1 (Sepharial Ch.XIV)', 'QUY_TAC', 28, 3, '1', '{"chi_so": "SEPHARIAL_CHIA_KHOA", "bang": 1}', 'Theo Sepharial (Ch.XIV, tr.139–140): Sách không nêu nghề nghiệp cụ thể cho số 1 trong Chương XIV (chỉ nêu rõ cho các số 3, 5, 9); tuy nhiên theo đặc tính Mặt Trời ở Chương IV (tr.45), số 1 có khuynh hướng hợp với vai trò tự chủ và dẫn dắt.', 'DI_THE_NAO', 5, 'Ch.XIV', 139, 140, 'THAP', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(433, 'KAB-SEP-HOP-KHAC-1', 'Quan hệ Số hợp / khắc của Số chìa khoá 1 (Sepharial Ch.XIV)', 'QUY_TAC', 28, 3, '1', '{"chi_so": "SEPHARIAL_CHIA_KHOA", "bang": 1}', 'Theo bảng tương hợp của Sepharial (Ch.IV & Ch.XIV), Số 1 đồng điệu với số 1, 3, 9 (cùng tầng Tinh thần Mặt Trời - Mộc tinh - Hoả tinh) và xung khắc với số 7, 8 (Thổ tinh).', 'DI_THE_NAO', 5, 'Ch.XIV', 139, 142, 'THAP', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(434, 'KAB-SEP-MAU-1', 'Màu sắc tương ứng với Số 1: Trắng (White) (Sepharial Ch.V)', 'QUY_TAC', 28, 3, '1', '{"chi_so": "SEPHARIAL_CHIA_KHOA", "bang": 1}', 'Theo Sepharial (Ch.V, tr.58–60), gợi ý văn hoá về màu sắc tương ứng với rung động của Số 1 là màu Trắng (White).', 'DI_THE_NAO', 5, 'Ch.V', 58, 60, 'THAP', 'GOI_Y_VAN_HOA', 'Theo Mục 9.1: Màu sắc theo số của Sepharial gắn nhãn GOI_Y_VAN_HOA.', 1, 'DA_DUYET', 'system', 'admin', NULL),
(435, 'KAB-SEP-CHIA-KHOA-2', 'Số chìa khoá 2 — Hành tinh Mặt Trăng (Moon) (Sepharial)', 'QUY_TAC', 28, 3, '2', '{"chi_so": "SEPHARIAL_CHIA_KHOA", "bang": 2}', 'Theo Sepharial (Ch.IV, tr.44–45), Số chìa khoá 2 gắn với Mặt Trăng, biểu thị tính mềm dẻo, linh hoạt (flexibility), nhạy bén với sự dịch chuyển và biến đổi. (Hành tinh theo Bảng chính Ch.III: Mặt Trăng (Moon); theo Bảng Khoá nhỏ Ch.IV: Mặt Trăng (Hạ giới - Thể chất)).', 'AI', 5, 'Ch.IV & XIV', 45, 140, 'THAP', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(436, 'KAB-SEP-NGHE-2', 'Khuynh hướng nghề nghiệp theo Số chìa khoá 2 (Sepharial Ch.XIV)', 'QUY_TAC', 28, 3, '2', '{"chi_so": "SEPHARIAL_CHIA_KHOA", "bang": 2}', 'Theo Sepharial (Ch.XIV, tr.139–140): Sách không nêu nghề nghiệp cụ thể cho số 2 trong Chương XIV; theo Chương IV (tr.44–45), số 2 gắn với sự dịch chuyển, giao lưu và kết nối linh hoạt (khi kết hợp với số 6 sẽ thiên về nghệ thuật, âm nhạc).', 'DI_THE_NAO', 5, 'Ch.XIV', 139, 140, 'THAP', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(437, 'KAB-SEP-HOP-KHAC-2', 'Quan hệ Số hợp / khắc của Số chìa khoá 2 (Sepharial Ch.XIV)', 'QUY_TAC', 28, 3, '2', '{"chi_so": "SEPHARIAL_CHIA_KHOA", "bang": 2}', 'Theo Sepharial (Ch.IV, tr.44), Số 2 hài hoà khi đi cùng số 6 (Kim tinh) hoặc số 7, và xung khắc mạnh với số 8 (Thổ tinh).', 'DI_THE_NAO', 5, 'Ch.XIV', 139, 142, 'THAP', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(438, 'KAB-SEP-MAU-2', 'Màu sắc tương ứng với Số 2: Vàng (Yellow) (Sepharial Ch.V)', 'QUY_TAC', 28, 3, '2', '{"chi_so": "SEPHARIAL_CHIA_KHOA", "bang": 2}', 'Theo Sepharial (Ch.V, tr.58–60), gợi ý văn hoá về màu sắc tương ứng với rung động của Số 2 là màu Vàng (Yellow).', 'DI_THE_NAO', 5, 'Ch.V', 58, 60, 'THAP', 'GOI_Y_VAN_HOA', 'Theo Mục 9.1: Màu sắc theo số của Sepharial gắn nhãn GOI_Y_VAN_HOA.', 1, 'DA_DUYET', 'system', 'admin', NULL),
(439, 'KAB-SEP-CHIA-KHOA-3', 'Số chìa khoá 3 — Hành tinh Hoả tinh (Mars - Bảng chính Ch.III) (Sepharial)', 'QUY_TAC', 28, 3, '3', '{"chi_so": "SEPHARIAL_CHIA_KHOA", "bang": 3}', 'Theo Sepharial (Ch.IV, tr.45 & Ch.XIV, tr.139), Số chìa khoá 3 biểu thị sự mở rộng, phát triển, tinh thần lạc quan (expansion, optimism, growth) và tư tưởng triết học. (Hành tinh theo Bảng chính Ch.III: Hoả tinh (Mars - Bảng chính Ch.III); theo Bảng Khoá nhỏ Ch.IV: Mộc tinh (Jupiter - Bảng Khoá nhỏ Ch.IV)).', 'AI', 5, 'Ch.IV & XIV', 45, 140, 'THAP', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(440, 'KAB-SEP-NGHE-3', 'Khuynh hướng nghề nghiệp theo Số chìa khoá 3 (Sepharial Ch.XIV)', 'QUY_TAC', 28, 3, '3', '{"chi_so": "SEPHARIAL_CHIA_KHOA", "bang": 3}', 'Theo Sepharial (Ch.XIV, tr.139), sách nêu rõ Số chìa khoá 3 ứng với khuynh hướng thần học, triết học, tư tưởng và giáo dục (''the number 3 answers to the theological'').', 'DI_THE_NAO', 5, 'Ch.XIV', 139, 140, 'THAP', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(441, 'KAB-SEP-HOP-KHAC-3', 'Quan hệ Số hợp / khắc của Số chìa khoá 3 (Sepharial Ch.XIV)', 'QUY_TAC', 28, 3, '3', '{"chi_so": "SEPHARIAL_CHIA_KHOA", "bang": 3}', 'Theo Sepharial (Ch.XIV, tr.139), Số 3 đồng điệu (syntonic) với số 3, cộng hưởng hài hoà (sympathetic) với số 6, bất hoà (discordant) với số 5 và đối kháng (in opposition) với số 8.', 'DI_THE_NAO', 5, 'Ch.XIV', 139, 142, 'THAP', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(442, 'KAB-SEP-MAU-3', 'Màu sắc tương ứng với Số 3: Tím (Violet) (Sepharial Ch.V)', 'QUY_TAC', 28, 3, '3', '{"chi_so": "SEPHARIAL_CHIA_KHOA", "bang": 3}', 'Theo Sepharial (Ch.V, tr.58–60), gợi ý văn hoá về màu sắc tương ứng với rung động của Số 3 là màu Tím (Violet).', 'DI_THE_NAO', 5, 'Ch.V', 58, 60, 'THAP', 'GOI_Y_VAN_HOA', 'Theo Mục 9.1: Màu sắc theo số của Sepharial gắn nhãn GOI_Y_VAN_HOA.', 1, 'DA_DUYET', 'system', 'admin', NULL),
(443, 'KAB-SEP-CHIA-KHOA-4', 'Số chìa khoá 4 — Hành tinh Thuỷ tinh (Mercury - Bảng chính Ch.III) (Sepharial)', 'QUY_TAC', 28, 3, '4', '{"chi_so": "SEPHARIAL_CHIA_KHOA", "bang": 4}', 'Theo Sepharial (Ch.IV, tr.44, 46), Số chìa khoá 4 biểu thị xu hướng thực tiễn (practical tendency), năng lực hiện thực hoá ý tưởng thành kết quả vật chất cụ thể (realisation). (Hành tinh theo Bảng chính Ch.III: Thuỷ tinh (Mercury - Bảng chính Ch.III); theo Bảng Khoá nhỏ Ch.IV: Mặt Trời (Hạ giới - Thể chất Ch.IV)).', 'AI', 5, 'Ch.IV & XIV', 45, 140, 'THAP', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(444, 'KAB-SEP-NGHE-4', 'Khuynh hướng nghề nghiệp theo Số chìa khoá 4 (Sepharial Ch.XIV)', 'QUY_TAC', 28, 3, '4', '{"chi_so": "SEPHARIAL_CHIA_KHOA", "bang": 4}', 'Theo Sepharial (Ch.XIV, tr.139–140): Sách không nêu nghề nghiệp cụ thể cho số 4 trong Chương XIV; theo Chương IV (tr.44, 46), số 4 thiên về các công việc thực thi và tạo ra kết quả thực chất.', 'DI_THE_NAO', 5, 'Ch.XIV', 139, 140, 'THAP', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(445, 'KAB-SEP-HOP-KHAC-4', 'Quan hệ Số hợp / khắc của Số chìa khoá 4 (Sepharial Ch.XIV)', 'QUY_TAC', 28, 3, '4', '{"chi_so": "SEPHARIAL_CHIA_KHOA", "bang": 4}', 'Theo Sepharial (Ch.IV, tr.44), người có tổng ngày sinh bằng 4 thuận lợi với những ngày và người mang giá trị số 4, 1, 5; và xung khắc với số 8 (Thổ tinh đối kháng Mặt Trời hạ giới 4).', 'DI_THE_NAO', 5, 'Ch.XIV', 139, 142, 'THAP', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(446, 'KAB-SEP-MAU-4', 'Màu sắc tương ứng với Số 4: Cam (Orange) (Sepharial Ch.V)', 'QUY_TAC', 28, 3, '4', '{"chi_so": "SEPHARIAL_CHIA_KHOA", "bang": 4}', 'Theo Sepharial (Ch.V, tr.58–60), gợi ý văn hoá về màu sắc tương ứng với rung động của Số 4 là màu Cam (Orange).', 'DI_THE_NAO', 5, 'Ch.V', 58, 60, 'THAP', 'GOI_Y_VAN_HOA', 'Theo Mục 9.1: Màu sắc theo số của Sepharial gắn nhãn GOI_Y_VAN_HOA.', 1, 'DA_DUYET', 'system', 'admin', NULL),
(447, 'KAB-SEP-CHIA-KHOA-5', 'Số chìa khoá 5 — Hành tinh Mộc tinh (Jupiter - Bảng chính Ch.III) (Sepharial)', 'QUY_TAC', 28, 3, '5', '{"chi_so": "SEPHARIAL_CHIA_KHOA", "bang": 5}', 'Theo Sepharial (Ch.IV, tr.44, 46), Số chìa khoá 5 biểu thị năng lực trí tuệ sắc bén (intellection), sự hiếu học, ngôn ngữ, khoa học và tính năng động trong giao thương. (Hành tinh theo Bảng chính Ch.III: Mộc tinh (Jupiter - Bảng chính Ch.III); theo Bảng Khoá nhỏ Ch.IV: Thuỷ tinh (Mercury - Bảng Khoá nhỏ Ch.IV)).', 'AI', 5, 'Ch.IV & XIV', 45, 140, 'THAP', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(448, 'KAB-SEP-NGHE-5', 'Khuynh hướng nghề nghiệp theo Số chìa khoá 5 (Sepharial Ch.XIV)', 'QUY_TAC', 28, 3, '5', '{"chi_so": "SEPHARIAL_CHIA_KHOA", "bang": 5}', 'Theo Sepharial (Ch.XIV, tr.139), sách nêu rõ Số chìa khoá 5 ứng với năng lực thương mại, kinh doanh và giao dịch (''5, in terms of the same kabala, answers to the commercial''), đồng thời ở Ch.IV (tr.46) gắn với khoa học và ngôn ngữ.', 'DI_THE_NAO', 5, 'Ch.XIV', 139, 140, 'THAP', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(449, 'KAB-SEP-HOP-KHAC-5', 'Quan hệ Số hợp / khắc của Số chìa khoá 5 (Sepharial Ch.XIV)', 'QUY_TAC', 28, 3, '5', '{"chi_so": "SEPHARIAL_CHIA_KHOA", "bang": 5}', 'Theo Sepharial (Ch.XIV, tr.139), Số 5 có mối quan hệ cộng hưởng với số 9 (khi kết hợp năng lực thương mại và điều hành), đồng điệu với số 6, nhưng bất hoà với bản chất thần học của số 3.', 'DI_THE_NAO', 5, 'Ch.XIV', 139, 142, 'THAP', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(450, 'KAB-SEP-MAU-5', 'Màu sắc tương ứng với Số 5: Chàm (Indigo) (Sepharial Ch.V)', 'QUY_TAC', 28, 3, '5', '{"chi_so": "SEPHARIAL_CHIA_KHOA", "bang": 5}', 'Theo Sepharial (Ch.V, tr.58–60), gợi ý văn hoá về màu sắc tương ứng với rung động của Số 5 là màu Chàm (Indigo).', 'DI_THE_NAO', 5, 'Ch.V', 58, 60, 'THAP', 'GOI_Y_VAN_HOA', 'Theo Mục 9.1: Màu sắc theo số của Sepharial gắn nhãn GOI_Y_VAN_HOA.', 1, 'DA_DUYET', 'system', 'admin', NULL),
(451, 'KAB-SEP-CHIA-KHOA-6', 'Số chìa khoá 6 — Hành tinh Kim tinh (Venus) (Sepharial)', 'QUY_TAC', 28, 3, '6', '{"chi_so": "SEPHARIAL_CHIA_KHOA", "bang": 6}', 'Theo Sepharial (Ch.IV, tr.44, 46), Số chìa khoá 6 gắn với Kim tinh, đại diện cho năng khiếu nghệ thuật, thơ ca, âm nhạc, sự tinh tế trong giao tế xã hội và lòng nhân ái, thiện cảm. (Hành tinh theo Bảng chính Ch.III: Kim tinh (Venus); theo Bảng Khoá nhỏ Ch.IV: Kim tinh (Trí óc Ch.IV)).', 'AI', 5, 'Ch.IV & XIV', 45, 140, 'THAP', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(452, 'KAB-SEP-NGHE-6', 'Khuynh hướng nghề nghiệp theo Số chìa khoá 6 (Sepharial Ch.XIV)', 'QUY_TAC', 28, 3, '6', '{"chi_so": "SEPHARIAL_CHIA_KHOA", "bang": 6}', 'Theo Sepharial (Ch.XIV, tr.139–140): Sách không tách mục nghề riêng cho số 6 ở Chương XIV; theo Chương IV (tr.44, 46), số 6 có khuynh hướng rõ rệt về nghệ thuật, âm nhạc, mỹ thuật và ngoại giao xã hội.', 'DI_THE_NAO', 5, 'Ch.XIV', 139, 140, 'THAP', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(453, 'KAB-SEP-HOP-KHAC-6', 'Quan hệ Số hợp / khắc của Số chìa khoá 6 (Sepharial Ch.XIV)', 'QUY_TAC', 28, 3, '6', '{"chi_so": "SEPHARIAL_CHIA_KHOA", "bang": 6}', 'Theo Sepharial (Ch.IV & Ch.XIV, tr.139), Số 6 có quan hệ cộng hưởng hài hoà (sympathetic) rất tốt với số 3, số 2 và số 5.', 'DI_THE_NAO', 5, 'Ch.XIV', 139, 142, 'THAP', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(454, 'KAB-SEP-MAU-6', 'Màu sắc tương ứng với Số 6: Xanh nhạt (Light Blue) (Sepharial Ch.V)', 'QUY_TAC', 28, 3, '6', '{"chi_so": "SEPHARIAL_CHIA_KHOA", "bang": 6}', 'Theo Sepharial (Ch.V, tr.58–60), gợi ý văn hoá về màu sắc tương ứng với rung động của Số 6 là màu Xanh nhạt (Light Blue).', 'DI_THE_NAO', 5, 'Ch.V', 58, 60, 'THAP', 'GOI_Y_VAN_HOA', 'Theo Mục 9.1: Màu sắc theo số của Sepharial gắn nhãn GOI_Y_VAN_HOA.', 1, 'DA_DUYET', 'system', 'admin', NULL),
(455, 'KAB-SEP-CHIA-KHOA-7', 'Số chìa khoá 7 — Hành tinh Thổ tinh (Saturn - Bảng chính Ch.III) (Sepharial)', 'QUY_TAC', 28, 3, '7', '{"chi_so": "SEPHARIAL_CHIA_KHOA", "bang": 7}', 'Theo Sepharial (Ch.IV, tr.46), Số chìa khoá 7 biểu thị năng lực tâm thức (psychic force), sức ảnh hưởng quần chúng, sự đa tài (versatility) và những chuyến đi xa. (Hành tinh theo Bảng chính Ch.III: Thổ tinh (Saturn - Bảng chính Ch.III); theo Bảng Khoá nhỏ Ch.IV: Mặt Trăng (Thượng giới - Trí óc Ch.IV)).', 'AI', 5, 'Ch.IV & XIV', 45, 140, 'THAP', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(456, 'KAB-SEP-NGHE-7', 'Khuynh hướng nghề nghiệp theo Số chìa khoá 7 (Sepharial Ch.XIV)', 'QUY_TAC', 28, 3, '7', '{"chi_so": "SEPHARIAL_CHIA_KHOA", "bang": 7}', 'Theo Sepharial (Ch.XIV, tr.139–140): Sách không nêu nghề nghiệp riêng cho số 7 trong Chương XIV; theo Chương IV (tr.46), số 7 gắn với các hoạt động đòi hỏi sự linh hoạt, đi lại và ảnh hưởng tinh thần.', 'DI_THE_NAO', 5, 'Ch.XIV', 139, 140, 'THAP', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(457, 'KAB-SEP-HOP-KHAC-7', 'Quan hệ Số hợp / khắc của Số chìa khoá 7 (Sepharial Ch.XIV)', 'QUY_TAC', 28, 3, '7', '{"chi_so": "SEPHARIAL_CHIA_KHOA", "bang": 7}', 'Theo Sepharial (Ch.IV, tr.42–46), Số 7 hài hoà với số 2, 5, 6 trên tầng Trí óc và xung khắc với số 8.', 'DI_THE_NAO', 5, 'Ch.XIV', 139, 142, 'THAP', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(458, 'KAB-SEP-MAU-7', 'Màu sắc tương ứng với Số 7: Bạc (Silver) (Sepharial Ch.V)', 'QUY_TAC', 28, 3, '7', '{"chi_so": "SEPHARIAL_CHIA_KHOA", "bang": 7}', 'Theo Sepharial (Ch.V, tr.58–60), gợi ý văn hoá về màu sắc tương ứng với rung động của Số 7 là màu Bạc (Silver).', 'DI_THE_NAO', 5, 'Ch.V', 58, 60, 'THAP', 'GOI_Y_VAN_HOA', 'Theo Mục 9.1: Màu sắc theo số của Sepharial gắn nhãn GOI_Y_VAN_HOA.', 1, 'DA_DUYET', 'system', 'admin', NULL),
(459, 'KAB-SEP-CHIA-KHOA-8', 'Số chìa khoá 8 — Hành tinh Thiên Vương tinh (Uranus - Bảng chính Ch.III) (Sepharial)', 'QUY_TAC', 28, 3, '8', '{"chi_so": "SEPHARIAL_CHIA_KHOA", "bang": 8}', 'Theo Sepharial (Ch.IV, tr.45–46), Số 8 gắn với thử thách của vật chất nhằm thúc đẩy quá trình chuyển hoá và tiến hoá tâm hồn: đòi hỏi bạn phải vượt qua những giới hạn khắt khe để trưởng thành. (Hành tinh theo Bảng chính Ch.III: Thiên Vương tinh (Uranus - Bảng chính Ch.III); theo Bảng Khoá nhỏ Ch.IV: Thổ tinh (Saturn - Thể chất Ch.IV)).', 'AI', 5, 'Ch.IV & XIV', 45, 140, 'THAP', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(460, 'KAB-SEP-NGHE-8', 'Khuynh hướng nghề nghiệp theo Số chìa khoá 8 (Sepharial Ch.XIV)', 'QUY_TAC', 28, 3, '8', '{"chi_so": "SEPHARIAL_CHIA_KHOA", "bang": 8}', 'Theo Sepharial (Ch.XIV, tr.139–140): Sách không nêu nghề nghiệp riêng cho số 8 trong Chương XIV; Sepharial lưu ý người số 8 cần chọn môi trường bền vững và tránh các liên kết xung khắc.', 'DI_THE_NAO', 5, 'Ch.XIV', 139, 140, 'THAP', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(461, 'KAB-SEP-HOP-KHAC-8', 'Quan hệ Số hợp / khắc của Số chìa khoá 8 (Sepharial Ch.XIV)', 'QUY_TAC', 28, 3, '8', '{"chi_so": "SEPHARIAL_CHIA_KHOA", "bang": 8}', 'Theo Sepharial (Ch.IV tr.44 & Ch.XIV tr.139), Số 8 đối kháng với số 3, số 4 và số 2; đồng điệu với chính số 8.', 'DI_THE_NAO', 5, 'Ch.XIV', 139, 142, 'THAP', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(462, 'KAB-SEP-MAU-8', 'Màu sắc tương ứng với Số 8: Đen (Black) (Sepharial Ch.V)', 'QUY_TAC', 28, 3, '8', '{"chi_so": "SEPHARIAL_CHIA_KHOA", "bang": 8}', 'Theo Sepharial (Ch.V, tr.58–60), gợi ý văn hoá về màu sắc tương ứng với rung động của Số 8 là màu Đen (Black).', 'DI_THE_NAO', 5, 'Ch.V', 58, 60, 'THAP', 'GOI_Y_VAN_HOA', 'Theo Mục 9.1: Màu sắc theo số của Sepharial gắn nhãn GOI_Y_VAN_HOA.', 1, 'DA_DUYET', 'system', 'admin', NULL),
(463, 'KAB-SEP-CHIA-KHOA-9', 'Số chìa khoá 9 — Hành tinh Hải Vương tinh (Neptune - Bảng chính Ch.III) (Sepharial)', 'QUY_TAC', 28, 3, '9', '{"chi_so": "SEPHARIAL_CHIA_KHOA", "bang": 9}', 'Theo Sepharial (Ch.IV, tr.46 & Ch.XIV, tr.139), Số chìa khoá 9 biểu thị khát vọng tự do, nguồn năng lượng dồi dào, sự sắc sảo, nhiệt huyết (zeal, acumen) và bản lĩnh hành động. (Hành tinh theo Bảng chính Ch.III: Hải Vương tinh (Neptune - Bảng chính Ch.III); theo Bảng Khoá nhỏ Ch.IV: Hoả tinh (Mars - Tinh thần Ch.IV)).', 'AI', 5, 'Ch.IV & XIV', 45, 140, 'THAP', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(464, 'KAB-SEP-NGHE-9', 'Khuynh hướng nghề nghiệp theo Số chìa khoá 9 (Sepharial Ch.XIV)', 'QUY_TAC', 28, 3, '9', '{"chi_so": "SEPHARIAL_CHIA_KHOA", "bang": 9}', 'Theo Sepharial (Ch.XIV, tr.139), sách nêu rõ Số chìa khoá 9 đại diện cho năng lực điều hành, quản trị và thực thi (''let 9 respond to and represent the executive faculty'').', 'DI_THE_NAO', 5, 'Ch.XIV', 139, 140, 'THAP', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(465, 'KAB-SEP-HOP-KHAC-9', 'Quan hệ Số hợp / khắc của Số chìa khoá 9 (Sepharial Ch.XIV)', 'QUY_TAC', 28, 3, '9', '{"chi_so": "SEPHARIAL_CHIA_KHOA", "bang": 9}', 'Theo Sepharial (Ch.IV & Ch.XIV, tr.139–140), Số 9 đồng điệu mạnh với số 1 và số 3 trên tầng Tinh thần (Mặt Trời - Mộc tinh - Hoả tinh).', 'DI_THE_NAO', 5, 'Ch.XIV', 139, 142, 'THAP', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(466, 'KAB-SEP-MAU-9', 'Màu sắc tương ứng với Số 9: Đỏ (Red) (Sepharial Ch.V)', 'QUY_TAC', 28, 3, '9', '{"chi_so": "SEPHARIAL_CHIA_KHOA", "bang": 9}', 'Theo Sepharial (Ch.V, tr.58–60), gợi ý văn hoá về màu sắc tương ứng với rung động của Số 9 là màu Đỏ (Red).', 'DI_THE_NAO', 5, 'Ch.V', 58, 60, 'THAP', 'GOI_Y_VAN_HOA', 'Theo Mục 9.1: Màu sắc theo số của Sepharial gắn nhãn GOI_Y_VAN_HOA.', 1, 'DA_DUYET', 'system', 'admin', NULL),
(467, 'KAB-SEP-MA-PHUONG-TINH_THAN', 'Tầng Tinh thần (3 - 1 - 9) chiếm ưu thế trên Ma phương Sepharial', 'QUY_TAC', 27, 3, 'TINH_THAN', '{"chi_so": "SEPHARIAL_TANG_UU_THE", "bang": "TINH_THAN"}', 'Theo Sepharial (Ch.IV, tr.42–43), hàng trên (3 - 1 - 9: Mộc tinh, Mặt Trời, Hoả tinh) đại diện cho tầng Tinh thần: khi các chữ số ngày tháng năm sinh tập trung nhiều ở tầng này, bạn có xu hướng đề cao tự do, lý tưởng mở rộng và bản lĩnh cá nhân.', 'AI', 5, 'Ch.IV', 41, 44, 'THAP', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(468, 'KAB-SEP-MA-PHUONG-TRI_OC', 'Tầng Trí óc (6 - 7 - 5) chiếm ưu thế trên Ma phương Sepharial', 'QUY_TAC', 27, 3, 'TRI_OC', '{"chi_so": "SEPHARIAL_TANG_UU_THE", "bang": "TRI_OC"}', 'Theo Sepharial (Ch.IV, tr.42–43), hàng giữa (6 - 7 - 5: Kim tinh, Mặt Trăng thượng giới, Thuỷ tinh) đại diện cho tầng Trí óc và Tâm hồn: bạn có thế mạnh về tư duy học thuật, cảm thụ nghệ thuật và khả năng thích ứng linh hoạt.', 'AI', 5, 'Ch.IV', 41, 44, 'THAP', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(469, 'KAB-SEP-MA-PHUONG-THE_CHAT', 'Tầng Thể chất (2 - 8 - 4) chiếm ưu thế trên Ma phương Sepharial', 'QUY_TAC', 27, 3, 'THE_CHAT', '{"chi_so": "SEPHARIAL_TANG_UU_THE", "bang": "THE_CHAT"}', 'Theo Sepharial (Ch.IV, tr.42–43), hàng dưới (2 - 8 - 4: Mặt Trăng hạ giới, Thổ tinh, Mặt Trời hạ giới) đại diện cho tầng Thể chất và Thực tiễn: bạn gắn bó chặt chẽ với việc hiện thực hoá kết quả cụ thể trong đời sống thực tế.', 'AI', 5, 'Ch.IV', 41, 44, 'THAP', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(470, 'KAB-SEP-CH13-TAROT-KHONG-DUNG', 'Phương pháp Tarot theo chu kỳ năm (The Kabalism of Cycles - Sepharial Ch.XIII)', 'LICH_SU', 28, 3, NULL, NULL, 'Phương pháp cộng tuổi với năm sinh để tra 22 lá ẩn chính Tarot dự đoán vận hạn từng năm trong Chương XIII của Sepharial. Đã bị loại khỏi trang Khám phá vì mang tính bói toán.', 'NEN_TANG', 5, 'Ch.XIII', 129, 137, 'THAP', 'KHONG_DUNG', 'Theo Mục 6.4 & 9.1: Nội dung bói toán / bảng âm vị tiếng Anh gắn nhãn KHONG_DUNG và loại LICH_SU.', 1, 'DA_DUYET', 'system', 'admin', NULL),
(471, 'KAB-SEP-CH07-XO-SO-KHONG-DUNG', 'Dự đoán sự kiện may rủi và xổ số (Chance Events - Sepharial Ch.VII)', 'LICH_SU', 28, 3, NULL, NULL, 'Các thử nghiệm dùng con số để dự đoán kết quả đua ngựa và sự kiện may rủi trong Chương VII của Sepharial.', 'NEN_TANG', 5, 'Ch.VII', 74, 82, 'THAP', 'KHONG_DUNG', 'Theo Mục 6.4 & 9.1: Nội dung bói toán / bảng âm vị tiếng Anh gắn nhãn KHONG_DUNG và loại LICH_SU.', 1, 'DA_DUYET', 'system', 'admin', NULL),
(472, 'KAB-SEP-CH10-DOC-Y-NGHI-KHONG-DUNG', 'Đọc ý nghĩ bằng con số (Thought-Reading by Numbers - Sepharial Ch.X–XI)', 'LICH_SU', 28, 3, NULL, NULL, 'Phương pháp tự động chọn số ngẫu nhiên để đoán câu hỏi trong tâm trí người khác trong Chương X và XI của Sepharial.', 'NEN_TANG', 5, 'Ch.X–XI', 102, 119, 'THAP', 'KHONG_DUNG', 'Theo Mục 6.4 & 9.1: Nội dung bói toán / bảng âm vị tiếng Anh gắn nhãn KHONG_DUNG và loại LICH_SU.', 1, 'DA_DUYET', 'system', 'admin', NULL),
(473, 'KAB-SEP-CH12-DO-THAT-LAC-KHONG-DUNG', 'Bói tìm đồ vật thất lạc (Of Things Lost - Sepharial Ch.XII)', 'LICH_SU', 28, 3, NULL, NULL, 'Phương pháp dùng số học để đoán vị trí đồ vật bị mất trong Chương XII của Sepharial.', 'NEN_TANG', 5, 'Ch.XII', 120, 128, 'THAP', 'KHONG_DUNG', 'Theo Mục 6.4 & 9.1: Nội dung bói toán / bảng âm vị tiếng Anh gắn nhãn KHONG_DUNG và loại LICH_SU.', 1, 'DA_DUYET', 'system', 'admin', NULL),
(474, 'KAB-SEP-CH15-CO-PHIEU-KHONG-DUNG', 'Dự đoán biến động giá cổ phiếu và hàng hoá (The Law of Values - Sepharial Ch.XV)', 'LICH_SU', 28, 3, NULL, NULL, 'Phương pháp áp dụng tỷ lệ số học để dự báo giá lúa mì, bông và cổ phiếu trong Chương XV của Sepharial.', 'NEN_TANG', 5, 'Ch.XV', 143, 161, 'THAP', 'KHONG_DUNG', 'Theo Mục 6.4 & 9.1: Nội dung bói toán / bảng âm vị tiếng Anh gắn nhãn KHONG_DUNG và loại LICH_SU.', 1, 'DA_DUYET', 'system', 'admin', NULL),
(475, 'KAB-SEP-BANG-AM-VI-LICH-SU', 'Bảng chữ cái âm vị (Phonetic Value) tiếng Anh của Sepharial (Ch.IV)', 'LICH_SU', 28, 3, NULL, NULL, 'Bảng quy đổi chữ cái theo âm phát âm tiếng Anh của Sepharial. Không áp dụng được cho hệ thống âm vị tiếng Việt nên được lưu làm tri thức lịch sử.', 'NEN_TANG', 5, 'Ch.IV', 38, 40, 'THAP', 'KHONG_DUNG', 'Theo Mục 6.4 & 9.1: Nội dung bói toán / bảng âm vị tiếng Anh gắn nhãn KHONG_DUNG và loại LICH_SU.', 1, 'DA_DUYET', 'system', 'admin', NULL);
